    }

  }


  public static boolean check(ArrayList<Point> points, int i){
    Point ith = points.get(i);
    int n = points.size();
    for(int j=0; j<n; ++j){
      if(j == i){
        continue;
      }
      for(int k=0; k<n; k++){
        if(k == i || k == j){
