class Point:
    def __init__(self, x1, x2, x3, x4, x5):
        self.x1 = x1
        self.x2 = x2
        self.x3 = x3
        self.x4 = x4
        self.x5 = x5

    def sq(self, x):
        return x * x

    def len_sq(self):
        return self.sq(self.x1) + self.sq(self.x2) + self.sq(self.x3) + self.sq(self.x4) + self.sq(self.x5)

    def prod(self, other):
        return (self.x1 * other.x1 + self.x2 * other.x2 +
                self.x3 * other.x3 + self.x4 * other.x4 + self.x5 * other.x5)

    def sub(self, other):
        return Point(self.x1 - other.x1, self.x2 - other.x2, self.x3 - other.x3, self.x4 - other.x4, self.x5 - other.x5)

def check(points, i):
    ith = points[i]
    n = len(points)
    for j in range(n):
        if j == i:
            continue
        for k in range(n):
            if k == i or k == j:
                continue
            x = points[j].sub(ith)
            y = points[k].sub(ith)
            if x.prod(y) > 0:
                return False
    return True

def main():
    import sys
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    if n > 11:
        print(0)
        return
    points = []
    index = 1
    for _ in range(n):
        x1 = int(input_data[index])
        x2 = int(input_data[index + 1])
        x3 = int(input_data[index + 2])
        x4 = int(input_data[index + 3])
        x5 = int(input_data[index + 4])
        index += 5
        points.append(Point(x1, x2, x3, x4, x5))
    ret = []
    for i in range(n):
        if check(points, i):
            ret.append(i + 1)
    print(len(ret))
    for x in ret:
        print(x)

if __name__ == "__main__":
    main()

